using System.Text;using System.Text.Json;using Microsoft.EntityFrameworkCore;using Nakama.Api.BuildingBlocks.Persistence;using Nakama.Api.BuildingBlocks.Time;using Nakama.Api.Modules.Identity.Authentication;using Nakama.Api.Modules.Notifications.Domain;
namespace Nakama.Api.Modules.Notifications;
public sealed record NotificationActorResponse(Guid Id,string FullName);public sealed record NotificationResponse(Guid Id,string Type,bool IsRead,DateTimeOffset CreatedAt,NotificationActorResponse? Actor,Guid? ProjectId,Guid? TaskId,JsonElement? Metadata);public sealed record NotificationFeedResponse(IReadOnlyList<NotificationResponse> Items,string? NextCursor);public sealed record NotificationCountResponse(int Count);public sealed record PreferenceResponse(string Type,bool Enabled);public sealed record UpdatePreferenceRequest(bool Enabled);
internal static class NotificationEndpoints{public static void Map(IEndpointRouteBuilder app){var g=app.MapGroup("/api/me").RequireAuthorization(Policies.AuthenticatedUser);g.MapGet("/notifications",List);g.MapGet("/notifications/unread-count",Count);g.MapPost("/notifications/{id:guid}/read",Read);g.MapPost("/notifications/read-all",ReadAll);g.MapGet("/notification-preferences",Preferences);g.MapPut("/notification-preferences/{type}",UpdatePreference);}static async Task<IResult> List(bool? unreadOnly,string? cursor,int? limit,NakamaDbContext db,ICurrentUser me,CancellationToken ct){var q=from n in db.Notifications.AsNoTracking() join u in db.Users.AsNoTracking() on n.ActorUserId equals u.Id into actors from a in actors.DefaultIfEmpty() where n.RecipientUserId==me.UserId&&(unreadOnly!=true||n.ReadAt==null) select new{n,a};var rows=await q.OrderByDescending(x=>x.n.CreatedAt).ThenByDescending(x=>x.n.Id).Take(Math.Clamp(limit??50,1,100)).ToListAsync(ct);return Results.Ok(new NotificationFeedResponse(rows.Select(x=>new NotificationResponse(x.n.Id,x.n.Type.ToString(),x.n.IsRead,x.n.CreatedAt,x.a==null?null:new(x.a.Id,x.a.FullName),x.n.ProjectId,x.n.TaskId,x.n.MetadataJson==null?null:JsonDocument.Parse(x.n.MetadataJson).RootElement.Clone())).ToList(),null));}static Task<IResult> Count(NakamaDbContext db,ICurrentUser me,CancellationToken ct)=>db.Notifications.CountAsync(x=>x.RecipientUserId==me.UserId&&x.ReadAt==null,ct).ContinueWith<IResult>(x=>Results.Ok(new NotificationCountResponse(x.Result)),ct);static async Task<IResult> Read(Guid id,NakamaDbContext db,IClock clock,ICurrentUser me,CancellationToken ct){var n=await db.Notifications.SingleOrDefaultAsync(x=>x.Id==id&&x.RecipientUserId==me.UserId,ct);if(n==null)return Results.NotFound();n.MarkRead(clock);await db.SaveChangesAsync(ct);return Results.NoContent();}static async Task<IResult> ReadAll(NakamaDbContext db,IClock clock,ICurrentUser me,CancellationToken ct){foreach(var n in await db.Notifications.Where(x=>x.RecipientUserId==me.UserId&&x.ReadAt==null).ToListAsync(ct))n.MarkRead(clock);await db.SaveChangesAsync(ct);return Results.NoContent();}static async Task<IResult> Preferences(NakamaDbContext db,ICurrentUser me,CancellationToken ct){var p=await db.NotificationPreferences.Where(x=>x.UserId==me.UserId).ToDictionaryAsync(x=>x.Type,x=>x.IsEnabled,ct);return Results.Ok(Enum.GetValues<NotificationType>().Select(x=>new PreferenceResponse(x.ToString(),p.GetValueOrDefault(x,true))));}static async Task<IResult> UpdatePreference(string type,UpdatePreferenceRequest r,NakamaDbContext db,ICurrentUser me,CancellationToken ct){if(!Enum.TryParse<NotificationType>(type,false,out var value))return Results.BadRequest();var p=await db.NotificationPreferences.SingleOrDefaultAsync(x=>x.UserId==me.UserId&&x.Type==value,ct);if(p==null)db.NotificationPreferences.Add(NotificationPreference.Create(me.UserId,value,r.Enabled));else p.Set(r.Enabled);await db.SaveChangesAsync(ct);return Results.NoContent();}}
